sections.template:
G0 X{{container.x}} Y{{container.y}} F{{global.movement_speed}}
M117; Open Container
PAUSE
G0 Z{{container.z}} F{{global.decent_speed}}
ASPIRATE MM={{runtime.refill.fill_mm}} SPEED={{global.refilling_speed}}; Filling the syringe
WAIT S={{global.syringe_aspirate_wait}}
DISPENSE MM={{runtime.refill.priming_mm}} SPEED={{global.dispensing_speed * custom.priming_speed_factor}} RELATIVE=1; Prevent backlash the syringe
WAIT S={{global.syringe_prime_wait}}
G0 Z{{global.z_movement_pos_high}} F{{global.adcent_speed}}

DISPENSE MM={{runtime.spot.dispense_mm}} SPEED={{global.dispensing_speed}} RELATIVE=1
WAIT S={{grid.droplet_forming_time}}
G0 Z{{grid.z_contact}} F{{global.decent_speed}} ;position for liquid contact
G0 Z{{global.z_movement_pos_low}} F{{global.adcent_speed}}

G0 X{{runtime.spot.x:.3f}} Y{{runtime.spot.y:.3f}} F{{global.movement_speed}}
G0 Z{{global.z_movement_pos_low}} F{{global.decent_speed}}
DISPENSE MM={{runtime.spot.dispense_mm:.6f}} SPEED={{global.dispensing_speed}} RELATIVE=1
WAIT S={{spiral.droplet_forming_time}}
G0 Z{{spiral.z_contact}} F{{global.decent_speed}} ;position for liquid contact
G0 Z{{global.z_movement_pos_low}} F{{global.adcent_speed}}

G1 X{{runtime.spot.x:.3f}} Y{{runtime.spot.y:.3f}} F{{global.movement_speed}}
DISPENSE MM={{runtime.spot.dispense_mm:.6f}} SPEED={{global.dispensing_speed}} RELATIVE=1
WAIT S={{spiral.droplet_forming_time}}

DISPENSE MM={{runtime.spot.dispense_mm}} SPEED={{global.dispensing_speed}} RELATIVE=1
WAIT S={{cleaning.droplet_forming_time_cleaning}}
G0 Z{{grid.z_contact}} F{{global.decent_speed}} ;position for liquid contact
G0 Z{{global.z_movement_pos_low}} F{{global.adcent_speed}}

; Washing sequence
M117; Auto Washing
G0 Z{{global.z_movement_pos_high}} F{{global.adcent_speed}}
G0 X{{runtime.washing.x_start}} Y{{washing.washing_y_pos}} F{{global.movement_speed}}
G0 Z{{washing.washing_depth}} F{{global.decent_speed}}

M117; Emptying Syringe

G0 Z{{global.z_movement_pos_high}} F{{global.adcent_speed}} ; dispensing leftovers
G0 X{{container.x}} Y{{container.y}} F{{global.movement_speed}}
G0 Z{{container.z}} F{{global.decent_speed}}
DISPENSE MM={{runtime.rinse.min_mm}} SPEED={{global.dispensing_speed}}
WAIT S={{global.emptying_wait}}

ASPIRATE MM={{runtime.rinse.max_mm}} SPEED={{global.dispensing_speed}} ; rinse aspiration
WAIT S={{global.rinse_aspiration_wait}}
DISPENSE MM={{runtime.rinse.min_mm}} SPEED={{global.dispensing_speed}} ; rinse dispense
